	@Inject
	public Ros2GrammarAccess(GrammarProvider grammarProvider,
			RosGrammarAccess gaRos,
			BasicsGrammarAccess gaBasics,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaRos = gaRos;
		this.gaBasics = gaBasics;
		this.gaTerminals = gaTerminals;
		this.pPackage = new PackageElements();
		this.pAmentPackage = new AmentPackageElements();
		this.pPluginBase = new PluginBaseElements();
		this.pNode = new NodeElements();
		this.eLifecycleState = new LifecycleStateElements();
		this.pQualityOfService = new QualityOfServiceElements();
		this.pPublisher = new PublisherElements();
		this.pSubscriber = new SubscriberElements();
		this.pServiceServer = new ServiceServerElements();
		this.pServiceClient = new ServiceClientElements();
		this.pActionServer = new ActionServerElements();
		this.pActionClient = new ActionClientElements();
		this.pParameter = new ParameterElements();
		this.pAddedKeywordName = new AddedKeywordNameElements();
		this.pExtensionColonKey = new ExtensionColonKeyElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("de.fraunhofer.ipa.ros2.Ros2".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
